AZURE = [
    {"resourceGroup": "team-data", "costUSD": 120.50},
    {"resourceGroup": "team-app", "costUSD": 60.00},
]
AWS = [
    {"tag_team": "team-data", "unblended_cost": 80.25},
    {"tag_team": "team-ml", "unblended_cost": 210.25},
]
GCP = [
    {"label_team": "team-app", "cost": 45.00},
    {"label_team": "team-ml", "cost": 39.75},
]

def normalize_records():
    rows = []
    for r in AZURE:
        rows.append((r["resourceGroup"], r["costUSD"]))
    for r in AWS:
        rows.append((r["tag_team"], r["unblended_cost"]))
    for r in GCP:
        rows.append((r["label_team"], r["cost"]))
    return rows

def allocate(rows):
    totals = {}
    for team, cost in rows:
        totals[team] = totals.get(team, 0.0) + cost
    return totals

_rows = normalize_records()
_totals = allocate(_rows)
for _team in sorted(_totals):
    print(f"{_team}: ${_totals[_team]:.2f}")
print(f"Total spend: ${sum(_totals.values()):.2f}")
